from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
FILES = json.loads('"{\\"buster/sdk/__init__.py\\": \\"\\\\nfrom .api import BusterSDK\\\\nfrom .events import Event, EventPriority\\\\nfrom .registry import ServiceRegistry\\\\nfrom .lifecycle import ModuleLifecycle, LifecycleState\\\\nfrom .config import SafeConfig\\\\n\\", \\"buster/sdk/events.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom dataclasses import dataclass, field\\\\nfrom datetime import datetime, UTC\\\\nfrom enum import Enum\\\\nfrom typing import Any, Callable, Dict, List\\\\nimport uuid\\\\n\\\\n\\\\ndef now_utc() -> str:\\\\n    return datetime.now(UTC).replace(microsecond=0).isoformat().replace(\\\\\\"+00:00\\\\\\", \\\\\\"Z\\\\\\")\\\\n\\\\n\\\\nclass EventPriority(str, Enum):\\\\n    LOW = \\\\\\"low\\\\\\"\\\\n    NORMAL = \\\\\\"normal\\\\\\"\\\\n    HIGH = \\\\\\"high\\\\\\"\\\\n    CRITICAL = \\\\\\"critical\\\\\\"\\\\n\\\\n\\\\n@dataclass\\\\nclass Event:\\\\n    type: str\\\\n    source: str = \\\\\\"buster\\\\\\"\\\\n    payload: Dict[str, Any] = field(default_factory=dict)\\\\n    priority: EventPriority = EventPriority.NORMAL\\\\n    id: str = field(default_factory=lambda: str(uuid.uuid4()))\\\\n    timestamp: str = field(default_factory=now_utc)\\\\n\\\\n\\\\nclass UnifiedEventAPI:\\\\n    def __init__(self) -> None:\\\\n        self._subscribers: Dict[str, List[Callable[[Event], None]]] = {}\\\\n        self.history: List[Event] = []\\\\n\\\\n    def publish(self, event_type: str, payload: Dict[str, Any] | None = None, source: str = \\\\\\"buster\\\\\\", priority: EventPriority | str = EventPriority.NORMAL) -> Event:\\\\n        if isinstance(priority, str):\\\\n            priority = EventPriority(priority)\\\\n        event = Event(type=event_type, source=source, payload=payload or {}, priority=priority)\\\\n        self.history.append(event)\\\\n        for handler in self._subscribers.get(event_type, []):\\\\n            handler(event)\\\\n        for handler in self._subscribers.get(\\\\\\"*\\\\\\", []):\\\\n            handler(event)\\\\n        return event\\\\n\\\\n    def subscribe(self, event_type: str, handler: Callable[[Event], None]) -> None:\\\\n        self._subscribers.setdefault(event_type, []).append(handler)\\\\n\\\\n    def recent(self, limit: int = 20) -> List[Dict[str, Any]]:\\\\n        return [e.__dict__ for e in self.history[-limit:]]\\\\n\\", \\"buster/sdk/registry.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom typing import Any, Dict, Iterable\\\\n\\\\n\\\\nclass ServiceRegistry:\\\\n    def __init__(self) -> None:\\\\n        self._services: Dict[str, Any] = {}\\\\n\\\\n    def register(self, name: str, service: Any, replace: bool = True) -> Any:\\\\n        if not replace and name in self._services:\\\\n            raise KeyError(f\\\\\\"Service already registered: {name}\\\\\\")\\\\n        self._services[name] = service\\\\n        return service\\\\n\\\\n    def get(self, name: str, default: Any = None) -> Any:\\\\n        return self._services.get(name, default)\\\\n\\\\n    def require(self, name: str) -> Any:\\\\n        if name not in self._services:\\\\n            raise KeyError(f\\\\\\"Missing required service: {name}\\\\\\")\\\\n        return self._services[name]\\\\n\\\\n    def has(self, name: str) -> bool:\\\\n        return name in self._services\\\\n\\\\n    def names(self) -> list[str]:\\\\n        return sorted(self._services.keys())\\\\n\\\\n    def items(self) -> Iterable[tuple[str, Any]]:\\\\n        return self._services.items()\\\\n\\\\n    def status(self) -> Dict[str, Any]:\\\\n        return {\\\\\\"services\\\\\\": self.names(), \\\\\\"count\\\\\\": len(self._services)}\\\\n\\", \\"buster/sdk/lifecycle.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom enum import Enum\\\\nfrom typing import Any, Dict, Protocol\\\\n\\\\n\\\\nclass LifecycleState(str, Enum):\\\\n    CREATED = \\\\\\"created\\\\\\"\\\\n    STARTING = \\\\\\"starting\\\\\\"\\\\n    RUNNING = \\\\\\"running\\\\\\"\\\\n    STOPPING = \\\\\\"stopping\\\\\\"\\\\n    STOPPED = \\\\\\"stopped\\\\\\"\\\\n    ERROR = \\\\\\"error\\\\\\"\\\\n\\\\n\\\\nclass LifecycleModule(Protocol):\\\\n    def start(self) -> Dict[str, Any]: ...\\\\n    def stop(self) -> Dict[str, Any]: ...\\\\n    def status(self) -> Dict[str, Any]: ...\\\\n\\\\n\\\\nclass ModuleLifecycle:\\\\n    def __init__(self) -> None:\\\\n        self.modules: Dict[str, Any] = {}\\\\n        self.states: Dict[str, LifecycleState] = {}\\\\n\\\\n    def register(self, name: str, module: Any) -> None:\\\\n        self.modules[name] = module\\\\n        self.states[name] = LifecycleState.CREATED\\\\n\\\\n    def start(self, name: str) -> Dict[str, Any]:\\\\n        module = self.modules[name]\\\\n        self.states[name] = LifecycleState.STARTING\\\\n        try:\\\\n            result = module.start() if hasattr(module, \\\\\\"start\\\\\\") else {\\\\\\"running\\\\\\": True}\\\\n            self.states[name] = LifecycleState.RUNNING\\\\n            return {\\\\\\"module\\\\\\": name, \\\\\\"state\\\\\\": self.states[name].value, \\\\\\"result\\\\\\": result}\\\\n        except Exception as exc:\\\\n            self.states[name] = LifecycleState.ERROR\\\\n            return {\\\\\\"module\\\\\\": name, \\\\\\"state\\\\\\": \\\\\\"error\\\\\\", \\\\\\"error\\\\\\": str(exc)}\\\\n\\\\n    def stop(self, name: str) -> Dict[str, Any]:\\\\n        module = self.modules[name]\\\\n        self.states[name] = LifecycleState.STOPPING\\\\n        try:\\\\n            result = module.stop() if hasattr(module, \\\\\\"stop\\\\\\") else {\\\\\\"running\\\\\\": False}\\\\n            self.states[name] = LifecycleState.STOPPED\\\\n            return {\\\\\\"module\\\\\\": name, \\\\\\"state\\\\\\": self.states[name].value, \\\\\\"result\\\\\\": result}\\\\n        except Exception as exc:\\\\n            self.states[name] = LifecycleState.ERROR\\\\n            return {\\\\\\"module\\\\\\": name, \\\\\\"state\\\\\\": \\\\\\"error\\\\\\", \\\\\\"error\\\\\\": str(exc)}\\\\n\\\\n    def start_all(self) -> Dict[str, Any]:\\\\n        return {name: self.start(name) for name in list(self.modules)}\\\\n\\\\n    def stop_all(self) -> Dict[str, Any]:\\\\n        return {name: self.stop(name) for name in reversed(list(self.modules))}\\\\n\\\\n    def status(self) -> Dict[str, Any]:\\\\n        return {name: state.value for name, state in self.states.items()}\\\\n\\", \\"buster/sdk/config.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom pathlib import Path\\\\nfrom typing import Any, Dict\\\\nimport json\\\\n\\\\n\\\\nclass SafeConfig:\\\\n    def __init__(self, path: str | Path = \\\\\\"data/v6_safe_config.json\\\\\\") -> None:\\\\n        self.path = Path(path)\\\\n        self.data: Dict[str, Any] = {}\\\\n        self.load()\\\\n\\\\n    def load(self) -> Dict[str, Any]:\\\\n        if self.path.exists():\\\\n            try:\\\\n                self.data = json.loads(self.path.read_text(encoding=\\\\\\"utf-8\\\\\\"))\\\\n            except Exception:\\\\n                self.data = {}\\\\n        return self.data\\\\n\\\\n    def save(self) -> None:\\\\n        self.path.parent.mkdir(parents=True, exist_ok=True)\\\\n        self.path.write_text(json.dumps(self.data, indent=2), encoding=\\\\\\"utf-8\\\\\\")\\\\n\\\\n    def get(self, key: str, default: Any = None) -> Any:\\\\n        return self.data.get(key, default)\\\\n\\\\n    def set(self, key: str, value: Any) -> Any:\\\\n        self.data[key] = value\\\\n        self.save()\\\\n        return value\\\\n\\\\n    def status(self) -> Dict[str, Any]:\\\\n        return {\\\\\\"path\\\\\\": str(self.path), \\\\\\"keys\\\\\\": sorted(self.data.keys())}\\\\n\\", \\"buster/sdk/api.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom pathlib import Path\\\\nfrom typing import Any, Callable, Dict\\\\n\\\\nfrom .config import SafeConfig\\\\nfrom .events import UnifiedEventAPI, EventPriority, Event\\\\nfrom .lifecycle import ModuleLifecycle\\\\nfrom .registry import ServiceRegistry\\\\n\\\\n\\\\nclass BusterSDK:\\\\n    \\\\\\"\\\\\\"\\\\\\"Stable API surface for v6.\\\\\\"\\\\\\"\\\\\\"\\\\n\\\\n    def __init__(self, data_dir: str | Path = \\\\\\"data\\\\\\") -> None:\\\\n        self.data_dir = Path(data_dir)\\\\n        self.events = UnifiedEventAPI()\\\\n        self.registry = ServiceRegistry()\\\\n        self.lifecycle = ModuleLifecycle()\\\\n        self.config = SafeConfig(self.data_dir / \\\\\\"v6_safe_config.json\\\\\\")\\\\n\\\\n    def publish(self, event_type: str, payload: Dict[str, Any] | None = None, source: str = \\\\\\"sdk\\\\\\", priority: EventPriority | str = EventPriority.NORMAL) -> Event:\\\\n        return self.events.publish(event_type, payload, source, priority)\\\\n\\\\n    def subscribe(self, event_type: str, handler: Callable[[Event], None]) -> None:\\\\n        self.events.subscribe(event_type, handler)\\\\n\\\\n    def register_service(self, name: str, service: Any) -> Any:\\\\n        return self.registry.register(name, service)\\\\n\\\\n    def service(self, name: str, default: Any = None) -> Any:\\\\n        return self.registry.get(name, default)\\\\n\\\\n    def require_service(self, name: str) -> Any:\\\\n        return self.registry.require(name)\\\\n\\\\n    def register_module(self, name: str, module: Any) -> None:\\\\n        self.lifecycle.register(name, module)\\\\n        self.registry.register(name, module)\\\\n\\\\n    def start(self) -> Dict[str, Any]:\\\\n        result = self.lifecycle.start_all()\\\\n        self.publish(\\\\\\"sdk.started\\\\\\", {\\\\\\"modules\\\\\\": self.lifecycle.status()}, source=\\\\\\"sdk\\\\\\")\\\\n        return result\\\\n\\\\n    def stop(self) -> Dict[str, Any]:\\\\n        result = self.lifecycle.stop_all()\\\\n        self.publish(\\\\\\"sdk.stopped\\\\\\", {\\\\\\"modules\\\\\\": self.lifecycle.status()}, source=\\\\\\"sdk\\\\\\")\\\\n        return result\\\\n\\\\n    def observe(self, summary: str, source: str = \\\\\\"sdk\\\\\\", **payload: Any) -> Event:\\\\n        data = {\\\\\\"summary\\\\\\": summary}\\\\n        data.update(payload)\\\\n        return self.publish(\\\\\\"perception.observation\\\\\\", data, source=source)\\\\n\\\\n    def speak(self, message: str, reason: str = \\\\\\"sdk\\\\\\") -> Event:\\\\n        return self.publish(\\\\\\"companion.speech\\\\\\", {\\\\\\"message\\\\\\": message, \\\\\\"reason\\\\\\": reason}, source=\\\\\\"sdk\\\\\\")\\\\n\\\\n    def learn(self, pattern: str, data: Dict[str, Any] | None = None) -> Event:\\\\n        return self.publish(\\\\\\"learning.pattern\\\\\\", {\\\\\\"pattern\\\\\\": pattern, \\\\\\"data\\\\\\": data or {}}, source=\\\\\\"sdk\\\\\\")\\\\n\\\\n    def create_goal(self, title: str, **payload: Any) -> Event:\\\\n        data = {\\\\\\"title\\\\\\": title}\\\\n        data.update(payload)\\\\n        return self.publish(\\\\\\"mind.goal.created\\\\\\", data, source=\\\\\\"sdk\\\\\\")\\\\n\\\\n    def status(self) -> Dict[str, Any]:\\\\n        return {\\\\n            \\\\\\"services\\\\\\": self.registry.status(),\\\\n            \\\\\\"modules\\\\\\": self.lifecycle.status(),\\\\n            \\\\\\"events\\\\\\": len(self.events.history),\\\\n            \\\\\\"config\\\\\\": self.config.status(),\\\\n        }\\\\n\\", \\"buster/runtime/v6_foundation.py\\": \\"\\\\nfrom __future__ import annotations\\\\n\\\\nfrom pathlib import Path\\\\nfrom typing import Any, Dict\\\\n\\\\nfrom buster.sdk import BusterSDK\\\\n\\\\n\\\\nclass V6FoundationRuntime:\\\\n    def __init__(self, data_dir: str | Path = \\\\\\"data\\\\\\") -> None:\\\\n        self.sdk = BusterSDK(data_dir=data_dir)\\\\n        self.running = False\\\\n\\\\n    def start(self) -> Dict[str, Any]:\\\\n        self.running = True\\\\n        self.sdk.publish(\\\\\\"runtime.v6.start\\\\\\", {\\\\\\"running\\\\\\": True}, source=\\\\\\"v6_foundation\\\\\\")\\\\n        return {\\\\\\"running\\\\\\": True, \\\\\\"sdk\\\\\\": self.sdk.status()}\\\\n\\\\n    def stop(self) -> Dict[str, Any]:\\\\n        self.running = False\\\\n        self.sdk.publish(\\\\\\"runtime.v6.stop\\\\\\", {\\\\\\"running\\\\\\": False}, source=\\\\\\"v6_foundation\\\\\\")\\\\n        return {\\\\\\"running\\\\\\": False, \\\\\\"sdk\\\\\\": self.sdk.status()}\\\\n\\\\n    def status(self) -> Dict[str, Any]:\\\\n        return {\\\\\\"running\\\\\\": self.running, \\\\\\"sdk\\\\\\": self.sdk.status()}\\\\n\\", \\"test_v6_0_foundation_sdk.py\\": \\"\\\\nfrom buster.sdk import BusterSDK\\\\nfrom buster.runtime.v6_foundation import V6FoundationRuntime\\\\n\\\\n\\\\ndef test_sdk_events_and_services():\\\\n    sdk = BusterSDK(data_dir=\\\\\\"data\\\\\\")\\\\n    seen = []\\\\n    sdk.subscribe(\\\\\\"test.event\\\\\\", lambda event: seen.append(event))\\\\n    event = sdk.publish(\\\\\\"test.event\\\\\\", {\\\\\\"ok\\\\\\": True}, source=\\\\\\"test\\\\\\")\\\\n    assert event.type == \\\\\\"test.event\\\\\\"\\\\n    assert seen and seen[0].payload[\\\\\\"ok\\\\\\"] is True\\\\n\\\\n    service = object()\\\\n    sdk.register_service(\\\\\\"demo\\\\\\", service)\\\\n    assert sdk.require_service(\\\\\\"demo\\\\\\") is service\\\\n\\\\n\\\\ndef test_sdk_lifecycle_runtime():\\\\n    runtime = V6FoundationRuntime(data_dir=\\\\\\"data\\\\\\")\\\\n    status = runtime.start()\\\\n    assert status[\\\\\\"running\\\\\\"] is True\\\\n    assert runtime.status()[\\\\\\"running\\\\\\"] is True\\\\n    stopped = runtime.stop()\\\\n    assert stopped[\\\\\\"running\\\\\\"] is False\\\\n\\\\n\\\\ndef test_sdk_companion_learning_goal_helpers():\\\\n    sdk = BusterSDK(data_dir=\\\\\\"data\\\\\\")\\\\n    sdk.observe(\\\\\\"screen active\\\\\\", source=\\\\\\"test\\\\\\")\\\\n    sdk.speak(\\\\\\"Hello Adam\\\\\\", reason=\\\\\\"test\\\\\\")\\\\n    sdk.learn(\\\\\\"reusable pattern\\\\\\", {\\\\\\"project\\\\\\": \\\\\\"buster\\\\\\"})\\\\n    sdk.create_goal(\\\\\\"finish v6 foundation\\\\\\")\\\\n    assert sdk.status()[\\\\\\"events\\\\\\"] == 4\\\\n\\", \\"BUSTER_V6_FOUNDATION.md\\": \\"\\\\n# Buster AI Companion OS v6 Foundation\\\\n\\\\nv6 starts with a stable SDK and runtime foundation.\\\\n\\\\n## Core rule\\\\n\\\\nPlugins and subsystems should use the SDK instead of reaching into internal modules directly.\\\\n\\\\n```python\\\\nsdk.observe(...)\\\\nsdk.publish(...)\\\\nsdk.subscribe(...)\\\\nsdk.speak(...)\\\\nsdk.learn(...)\\\\nsdk.create_goal(...)\\\\nsdk.register_service(...)\\\\nsdk.register_module(...)\\\\n```\\\\n\\\\n## What this adds\\\\n\\\\n- Buster SDK\\\\n- Unified event API\\\\n- Service registry\\\\n- Module lifecycle\\\\n- Safe config layer\\\\n- v6 foundation runtime\\\\n\\\\n## Why\\\\n\\\\nBuster is now large enough that new systems need a stable internal API.\\\\n\\\\nThe SDK protects the architecture from becoming tightly coupled.\\\\n\\"}"')

def main():
    print("=== Applying Buster v6.0 Foundation SDK Patch ===")
    for rel, content in FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content.strip() + "\n", encoding="utf-8")
        print(f"[WRITE] {rel}")

    for rel in ["data/v6_safe_config.json", "data/v6_foundation_state.json"]:
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists():
            path.write_text("{}\n", encoding="utf-8")
            print(f"[CREATE] {rel}")
        else:
            print(f"[SKIP] {rel}")

    print("\nSUCCESS: Buster v6.0 Foundation SDK installed.")
    print("Next: python -m pytest")

if __name__ == "__main__":
    main()
